  // ---- 本番レース (Stage W / W3)。race.run〜race.hint/race.title は HTML 静的、他は JS が t() で生成 ----
  'race.run':         { ja: '🏁 レース', en: '🏁 Race' },
  'race.run.title':   { ja: '現在の車両編成 (各車のプログラム+車種) で決定論レースを実行し、順位・タイムとレースレポートを表示します。固定60Hz・ノイズOFF・処理順固定で同じ結果を再現できます (公式記録の土台)', en: "Run a deterministic race with the current line-up (each car's program + car type) and show standings, times, and a race report. Fixed 60 Hz, noise off, and a fixed processing order reproduce the same result (the basis for official records)." },
  'race.laps':        { ja: '周回', en: 'Laps' },
  'race.laps.title':  { ja: '完走に要する周回数', en: 'Laps required to finish' },
  'race.recon':       { ja: '試走', en: 'Recon' },
  'race.recon.title': { ja: 'レース前に各車が単独でコースを試走(recon)する周回数。0=従来(試走なし)。試走で覚えた地図を持って本番へ入るため、コースを学習するプログラム(Recon Racer 等)は本番1周目から先読み走行できます。試走は計時外・他車なし・決定論的に再現されます', en: 'Number of laps each car runs the course alone (recon) before the race. 0 = classic (no recon). Cars carry the learned map into the race, so course-learning programs (e.g. Recon Racer) can drive with look-ahead from lap 1. Recon is off-clock, solo, and reproduced deterministically.' },
  'race.rejoin':      { ja: 'クラッシュで復帰(+3秒)', en: 'Rejoin on crash (+3s)' },
  'race.rejoin.title':{ ja: 'ON=クラッシュしても3秒ペナルティを課して自動復帰し走り続ける / OFF=クラッシュでリタイア(DNF)。どちらでも結果は決定論的に再現できます', en: 'ON = on a crash, add a 3-second penalty and auto-recover to keep going / OFF = retire on crash (DNF). Either way the result is reproducible deterministically.' },
  'race.watch':       { ja: '観戦リプレイ(自動)', en: 'Auto replay' },
  'race.watch.title': { ja: 'ON=🏁レース後に自動で観戦リプレイ(決定論の結果をコース上で再生し、スタート→周回→ゴールを観戦)を始める / OFF=結果のみ(👻ボタンで手動再生)。レース計算には影響しません。', en: 'ON: after a 🏁 race, auto-play a spectator replay (the deterministic result replayed on the course — watch start → laps → finish). OFF: results only (replay manually with the 👻 button). Does not affect the race computation.' },
  'race.sfx':         { ja: '効果音', en: 'Sound FX' },
  'race.sfx.title':   { ja: 'ON=発走(3-2-1)・周回・ゴール・クラッシュの最小限の効果音を鳴らす / OFF=完全無音。音は presentation のみ＝レース計算や決定論には一切影響しません。', en: 'ON: play minimal sound effects for start (3-2-1), laps, finish and crashes / OFF: fully silent. Sound is presentation only — it never affects the race computation or determinism.' },
  'log.sfx.on':       { ja: '🔊 効果音 ON', en: '🔊 Sound FX on' },
  'log.sfx.off':      { ja: '🔇 効果音 OFF', en: '🔇 Sound FX off' },
  'ctl.refline':      { ja: 'お手本ライン', en: 'Reference line' },
  'ctl.refline.title': { ja: 'ON=走行の軌跡をなめらか化した「お手本ライン」(破線)を重ねて表示。左右中央の3値操舵で生じる蛇行に対する、理想のなめらかなラインの目安です(表示のみ＝走りには一切影響しません)。', en: 'ON: overlay a smoothed "reference line" (dashed) of the driven path. It is a guide to the ideal smooth line versus the weave caused by 3-state (left/center/right) steering — display only, it never affects driving.' },
  'log.refline.on':   { ja: '✏️ お手本ライン ON', en: '✏️ Reference line on' },
  'log.refline.off':  { ja: '✏️ お手本ライン OFF', en: '✏️ Reference line off' },
  'log.share.copied':  { ja: '🔗 共有リンクをコピーしました (このリンクを開くと現在の設定が再現されます)', en: '🔗 Copied share link (opening it reproduces the current settings)' },
  'log.share.copyFail': { ja: '🔗 共有リンクのコピーに失敗しました (ブラウザのクリップボード権限をご確認ください)', en: '🔗 Could not copy the share link (please check your browser clipboard permission)' },
  'log.share.restored': { ja: '🔗 共有リンクの設定を復元しました', en: '🔗 Restored settings from the shared link' },
  'log.share.course.missing':  { ja: '🔗 共有リンクのコース「{name}」が見つかりません。ランダムなコースで開始します (自作/投稿コースは共有リンクに含まれません)', en: '🔗 Shared course "{name}" was not found; starting with a random course (custom/community courses are not included in share links)' },
  'log.share.car.missing':     { ja: '🔗 共有リンクの車種「{key}」が見つかりません。既定の車種を使います', en: '🔗 Shared car "{key}" was not found; using the default car' },
  'log.share.program.missing': { ja: '🔗 共有リンクのプログラム「{key}」が見つかりません。既定を使います (自作/投稿プログラムは共有リンクに含まれません)', en: '🔗 Shared program "{key}" was not found; using the default (custom/community programs are not included in share links)' },
